const apiUrl = String.fromEnvironment('API_URL', defaultValue: 'http://10.0.2.2:3000');
const green = Color(0xFF0B5D47), orange = Color(0xFFFF7A00), cream = Color(0xFFFAF9F6);

class Api {
  String? token;
  Future<dynamic> send(String method, String path, [Object? body]) async {
    final req = http.Request(method, Uri.parse('$apiUrl$path'))..headers['Content-Type']='application/json';
    if (token != null) req.headers['Authorization']='Bearer $token';
    if (body != null) req.body=jsonEncode(body);
    final res = await http.Response.fromStream(await req.send().timeout(const Duration(seconds: 15)));
    final data = res.body.isEmpty ? null : jsonDecode(res.body);
    if (res.statusCode >= 400) throw Exception((data is Map ? data['error'] : null) ?? 'Request failed (${res.statusCode})');
    return data;
  }
}

void main() => runApp(const VendorApp());
class VendorApp extends StatelessWidget { const VendorApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(title:'Cönëct Vendor',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:green,secondary:orange),scaffoldBackgroundColor:cream,useMaterial3:true),home:const VendorGate()); }

class VendorGate extends StatefulWidget { const VendorGate({super.key}); @override State<VendorGate> createState()=>_VendorGateState(); }
class _VendorGateState extends State<VendorGate> {
  final api=Api(); bool ready=false;
  @override void initState(){super.initState(); _init();}
  Future<void> _init() async { final p=await SharedPreferences.getInstance(); api.token=p.getString('token'); if(api.token!=null){try{await api.send('GET','/vendor/profile');}catch(_){api.token=null;}} if(mounted)setState(()=>ready=true); }
  @override Widget build(BuildContext context)=>!ready?const Scaffold(body:Center(child:CircularProgressIndicator())):api.token==null?VendorLogin(api:api,onLogin:()async{final p=await SharedPreferences.getInstance();await p.setString('token',api.token!);if(mounted)setState(()=>ready=true);}):VendorDashboard(api:api,onSignOut:()async{api.token=null;final p=await SharedPreferences.getInstance();await p.remove('token');if(mounted)setState(()=>ready=true);});
}

class VendorLogin extends StatefulWidget { final Api api; final VoidCallback onLogin; const VendorLogin({super.key,required this.api,required this.onLogin}); @override State<VendorLogin> createState()=>_VendorLoginState(); }
