 Text('Manage your store and orders',textAlign:TextAlign.center),const SizedBox(height:24),TextField(controller:name,decoration:const InputDecoration(labelText:'Your full name (for registration)',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password',border:OutlineInputBorder())),if(error.isNotEmpty)Padding(padding:const EdgeInsets.all(8),child:Text(error,style:const TextStyle(color:Colors.red))),if(error.toLowerCase().contains('verify your email'))TextButton(onPressed:busy?null:()async{try{await widget.api.send('POST','/auth/resend-verification',{'email':email.text.trim()});setState(()=>error='If verification is needed, a new email will arrive shortly. Check spam/junk too.');}catch(e){setState(()=>error=e.toString().replaceFirst('Exception: ',''));}},child:const Text('Resend verification email')),FilledButton(onPressed:busy?null:()=>submit(),child:Text(busy?'Please wait…':'Sign in')),const SizedBox(height:8),OutlinedButton(onPressed:busy?null:()=>submit(register:true),child:const Text('Create vendor account'))])))))); }

class VendorDashboard extends StatefulWidget { final Api api; final VoidCallback onSignOut; const VendorDashboard({super.key,required this.api,required this.onSignOut}); @override State<VendorDashboard> createState()=>_VendorDashboardState(); }
class _VendorDashboardState extends State<VendorDashboard> { Map<String,dynamic>? data; List products=[],orders=[],documents=[]; bool busy=true; String error=''; final name=TextEditingController(),type=TextEditingController(text:'food'),phone=TextEditingController(),address=TextEditingController(),reg=TextEditingController(); final itemName=TextEditingController(),itemPrice=TextEditingController(); double? storeLat,storeLng; Future<void> load()async{try{final p=await widget.api.send('GET','/vendor/profile'); final docs=await widget.api.send('GET','/verification/documents'); final pr=p['approved']==true?await widget.api.send('GET','/vendor/products'):[]; final o=p['approved']==true?await widget.api.send('GET','/vendor/orders'):[]; if(mounted)setState(() { data=Map<String,dynamic>.from(p); products=pr; orders=o; documents=docs; busy=false; error=''; }); final profile=p['profile']; if(profile is Map){name.text=profile['business_name']??'';type.text=profile['business_type']??'food';phone.text=profile['phone']??'';address.text=profile['address']??'';reg.text=profile['registration_number']??'';}}catch(e){if(mounted)setState(() { error=e.toString(); busy=false; });}} @override void initState(){super.initState();load();}
Future<void> saveProfile()async{try{await widget.api.send('PUT','/vendor/profile',{'business_name':name.text.trim(),'business_type':type.text,'phone':phone.text.trim(),'address':address.text.trim(),'registration_number':reg.text.trim()});await load();msg('Profile saved. Submit your verification documents to the Cönëct admin team.');}catch(e){msg(e.toString());}}
Future<void> uploadDocument(String documentType)async{try{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['jpg','jpeg','png','pdf'],withData:true);if(result==null)return;final file=result.files.single;final bytes=file.bytes;if(bytes==null||bytes.isEmpty)throw Exception('Could not read the selected file.');if(bytes.length>2*1024*1024)throw Exception('Choose a file no larger than 2 MB.');final ext=(file.extension??'').toLowerCase();final mime=ext=='pdf'?'application/pdf':(ext=='png'?'image/png':'image/jpeg');await widget.api.send('POST','/verification/documents',{'document_type':documentType,'filename':file.name,'mime_type':mime,'data_base64':base64Encode(bytes)});await load();msg('Document submitted securely for review.');}catch(e){msg(e.toString().replaceFirst('Exception: ',''));}}
Future<void> captureStoreLocation()async{try{var permission=await Geolocator.checkPermission();if(permission==LocationPermission.denied)permission=await Geolocator.requestPermission();if(permission==LocationPermission.denied||permission==LocationPermission.deniedForever)throw Exception('Location permission is required to register your store.');final p=await Geolocator.getCurrentPosition();if(mounted)setState((){storeLat=p.latitude;storeLng=p.longitude;});msg('Store GPS location saved.');}catch(e){msg(e.toString().replaceFirst('Exception: ',''));}}
Future<void> createStore()async{if(storeLat==null||storeLng==null)return msg('Capture your store GPS location before creating the store.');try{await widget.api.send('POST','/vendor/store',{'lat':storeLat,'lng':storeLng,'delivery_fee':300});await load();msg('Store created closed and sent for review.');}catch(e){msg(e.toString());}}
Future<void> addProduct()async{try{await widget.api.send('POST','/vendor/products',{'name':itemName.text.trim(),'price':double.parse(itemPrice.text),'available':true});itemName.clear();itemPrice.clear();await load();}catch(e){msg(e.toString());}}
Future<void> changeOrderStatus(dynamic order,String status)async{try{await widget.api.send('PATCH','/vendor/orders/${order['id']}/status',{'status':status});await load();msg(status=='preparing'?'Order marked as preparing.':'Order marked ready for courier pickup.');}catch(e){msg(e.toString());}}
